before.lib/resolver.ex:
defmodule Resolver do
  @doc "Look up an ID with the catalog; an empty result means missing. Unexpected failures propagate."
  def provider_id(id, catalog) do
    case catalog.(id) do
      [program] -> {:ok, program.provider_id}
      [] -> {:error, :program_not_found}
    end
  end
end

